def fail(msg):
    raise SystemExit("26487 V2 FAIL: "+msg)

def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()


def numerical_self_test():
    rng=random.Random(26487)
    # Camera2 affine noise must follow the sample domain: y=a*x -> S'=a*S, O'=a^2*O.
    for _ in range(300):
        S=10**rng.uniform(-6,-2);O=10**rng.uniform(-10,-4);x=rng.random();a=10**rng.uniform(-0.7,0.8);y=a*x
        direct=a*a*(S*x+O); transformed=(a*S)*y+a*a*O
        if abs(direct-transformed)>max(1e-13,abs(direct)*1e-7): fail("Camera2 affine-noise identity")
    # MGC green LUT is 0.25*(Gr+Gb variance), then guide/covariance consume 2*LUT.G.
    for _ in range(300):
        s1=10**rng.uniform(-6,-2);s2=10**rng.uniform(-6,-2);o1=10**rng.uniform(-10,-4);o2=10**rng.uniform(-10,-4);signal=rng.random()
        recovered=2.0*0.25*((s1+s2)*signal+(o1+o2)); expected=0.5*((s1*signal+o1)+(s2*signal+o2))
        if abs(recovered-expected)>max(1e-13,abs(expected)*1e-7): fail("two-green variance identity")
    # Noise-only static burst should retain nearly the entire attempted stack.
    weights=[]
    for _ in range(90000):
        excess=[max(rng.gauss(0.0,1.0)**2-1.0,0.0) for _c in range(3)]
        distance=0.07*sum(excess)/3.0
        weights.append(2.0**(-distance))
    weights.sort(); mean=sum(weights)/len(weights); p10=weights[len(weights)//10]; median=weights[len(weights)//2]; support=1.0+14.0*mean
    if not(mean>0.95 and median>0.97 and p10>0.90 and support>14.0): fail(f"15-frame support collapsed mean={mean} p10={p10} support={support}")
    threshold=250.0/255.0
    def valid(q): return 1.0 if max(q)<threshold else 0.0
    if valid([threshold-1e-4]*4)!=1.0 or valid([0.2,0.3,threshold,0.4])!=0.0: fail("single clip authority")
    for qmax in (threshold-1e-5,threshold,threshold+1e-5,1.2):
        v=valid([0.2,0.3,0.4,qmax]); rg=(0.11*v)/(0.5*v) if v else 0.0; bg=(-0.07*v)/(0.5*v) if v else 0.0
        if not v and (rg!=0.0 or bg!=0.0): fail("censored opponent neutrality")
    # OOB flow may update diagnostics only; RGB numerator/denominator/support must remain unchanged.
    for _ in range(200):
        num=[rng.uniform(-2,2) for _ in range(4)];den=[rng.random()*5 for _ in range(4)];sup=[rng.random()*15 for _ in range(4)]
        n2=list(num);d2=list(den);s2=list(sup);s2[3]+=1.0
        if n2!=num or d2!=den or s2[:3]!=sup[:3]: fail("OOB state identity")
    # Exact 20-tap clipped Gaussian: offsets -9..10, sigma 500, cannot increase evidence.
    kernel=[math.exp(-(x*x)/(2.0*500.0*500.0)) for x in range(-9,11)]; z=sum(kernel); kernel=[v/z for v in kernel]
    if len(kernel)!=20 or abs(sum(kernel)-1.0)>1e-12: fail("clipped Gaussian kernel")
    for _ in range(100):
        center=rng.random(); f=sum(k*rng.random() for k in kernel)
        if min(center,f)>center+1e-15: fail("clipped Gaussian increased evidence")
    # Recovered dilation maps zero rejection to identity weight 1.
    mapped=1.0-((0.0-0.2)*0.5)
    if min(max(mapped,0.0),1.0)!=1.0: fail("dilation identity")
    print(f"26487 V2 NUMERICAL SELF-TEST PASS projected15FrameSupport={support:.6f} p10Weight={p10:.6f}")


def validate_post(root):
    for rel,want in POST.items():
        p=root/rel
        if not p.is_file(): fail("missing post file "+rel)
        got=sha(p)
        if got!=want: fail(f"post hash {rel} got={got} want={want}")
    def read(rel): return (root/rel).read_text()
    cap=read("app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java")
    gp=read("app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/GLProg.java")
    wr=read("app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2WronskiAlignment.java")
    recon=read("app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java")
    shaders={rel:read(rel) for rel in CHANGED_PATHS if rel.endswith('.glsl')}
    joined='\n'.join(shaders.values())+'\n'+recon
    # Reconstruction correctness owners.
    required=[
        (recon,"IRIS_26487_CAMERA2_PER_CFA_NOISE_AUTHORITY"),(recon,"IRIS_26487_RECONSTRUCTION_CORRECTNESS_BJZHOU_GRAPH"),
        (recon,"IRIS_26487_COARSE_SUPPORT_TELEMETRY_NO_FULLRES_READBACK"),(recon,"IRIS_26487_SINGLE_GPU_OWNERSHIP_DRAIN"),
        (recon,"final Point iris26487DiagSize = new Point(48,36)"),(recon,"IRIS_26487_PROCESSING_BUDGET"),
        (cap,"IRIS_26486_FREEZE_BUFFER_AT_SHUTTER_NO_TOPUP_WAIT"),(cap,"IRIS_26486_RING_REOPEN_ONLY_AFTER_IMMUTABLE_BATCH"),
        (cap,"IRIS_26487_SINGLE_ACTIVE_MOTION_PROCESSING_NO_BACKLOG"),(cap,"MOTION_26486_MAX_INFLIGHT_BATCHES = 1"),
        (gp,"IRIS_26487_MOTION_DEFERRED_GPU_SUBMISSION"),(gp,"computeAutoDeferred"),(gp,"glMemoryBarrier(GL_ALL_BARRIER_BITS)"),
        (gp,"finishDeferredCompute"),(wr,"IRIS_26487_WRONSKI_DEFERRED_GPU_CHAIN_NO_PER_DISPATCH_FINISH"),
        (shaders["app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl"],"IRIS_26487_CENSORED_OPPONENT_PRECISION_DIRECT_NO_OOB_LOSS"),
        (shaders["app/src/main/assets/shaders/motionv2/mfsr_wb_cfa.glsl"],"IRIS_26487_SINGLE_CLIPPING_AUTHORITY_WB_ONLY"),
        (shaders["app/src/main/assets/shaders/motionv2/mfsr_mgc_covariance.glsl"],"IRIS_26487_BJZHOU_COVARIANCE_EXACT_GEOMETRY"),
        (shaders["app/src/main/assets/shaders/motionv2/mfsr_bjzhou_rejection_base.glsl"],"IRIS_26487_BJZHOU_REJECTION_EXACT_EQUATION"),
        (shaders["app/src/main/assets/shaders/motionv2/mfsr_bjzhou_rejection_dilate.glsl"],"IRIS_26487_BJZHOU_DILATE_MASK_EXACT"),
        (shaders["app/src/main/assets/shaders/motionv2/mfsr_finalize.glsl"],"IRIS_26487_OPPONENT_NORMALIZE_ONCE_NO_SUPPORT_HUE_FADE"),
    ]
    for text,token in required:
        if token not in text: fail("missing semantic token "+token)
    # Legacy/non-Motion compute methods must remain synchronous. Deferred Motion methods must not finish per dispatch.
    legacy=re.search(r"public void computeAuto\(Point size, int z\) \{(.*?)\n    \}",gp,re.S)
    deferred=re.search(r"public void computeAutoDeferred\(Point size, int z\) \{(.*?)\n    \}",gp,re.S)
    finisher=re.search(r"public long finishDeferredCompute\(String label\) \{(.*?)\n    \}",gp,re.S)
    if not legacy or 'glFinish();' not in legacy.group(1): fail("legacy GLProg synchronization changed")
    if not deferred or 'glFinish();' in deferred.group(1) or 'GL_ALL_BARRIER_BITS' not in deferred.group(1): fail("deferred Motion dispatch contract")
    if not finisher or finisher.group(1).count('glFinish();')!=1: fail("single deferred ownership drain missing")
    if 'glProg.computeAuto(' in recon or 'glProg.computeAuto(' in wr: fail("blocking computeAuto survived active Motion chain")
    if recon.count('glProg.computeAutoDeferred(')<25 or wr.count('glProg.computeAutoDeferred(')<10: fail("deferred Motion coverage incomplete")
    if recon.count('finishDeferredCompute("MotionV2 final image")')!=1: fail("Motion final ownership drain count")
    if 'mfsr_support_downsample' in recon: fail("full-resolution support readback path survived")
    if 'MOTION_26486_MAX_INFLIGHT_BATCHES = 2' in cap: fail("Motion processing backlog survived")
    zsl_start=cap.find('private void triggerZslCapture()')
    zsl_end=cap.find('private void captureStillPicture()',zsl_start)
    if zsl_start<0 or zsl_end<0: fail("Motion ZSL method scope missing")
    zsl=cap[zsl_start:zsl_end]
    if zsl.find('IRIS_26486_RING_REOPEN_ONLY_AFTER_IMMUTABLE_BATCH')<0: fail("Motion ring reopen marker missing")
    if zsl.find('IRIS_26486_RING_REOPEN_ONLY_AFTER_IMMUTABLE_BATCH')>zsl.find('processExecutor.execute(() ->'): fail("RAW ring reopens after processing enqueue")
    # Exact math/ownership negatives from earlier failed iterations.
    for token in ["repairClipped(","opposedEstimate(","physicalClipStart","physicalClipEnd","invertCov(","exp(-3.0","0.94f","0.985f","rgAuthority","localReliableHue","MotionV2IpolNoiseCurve"]:
        if token in joined: fail("forbidden stale reconstruction token "+token)
    acc=shaders["app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl"]
    final=shaders["app/src/main/assets/shaders/motionv2/mfsr_finalize.glsl"]
    short=shaders["app/src/main/assets/shaders/motionv2/short_highlight_recover.glsl"]
    if "s.a+=oob;imageStore(outNumerator,p,n);imageStore(outDenominator,p,d);imageStore(outFrameSupport,p,s);" not in acc: fail("OOB state preservation")
    if "den.y>1e-10?num.y/den.y:0.0" not in final: fail("opponent normalization")
    if "x/max(referenceExposureScale,1e-6)" not in short: fail("short physical domain")
    # Photon runtime Shader parser: one layout declaration per physical line.
    for rel,text in shaders.items():
        for no,line in enumerate(text.splitlines(),1):
            if line.count('layout(')>1: fail(f"runtime layout parser hazard {rel}:{no}")
    numerical_self_test()
    print("26487 V2 SOURCE SEMANTIC VALIDATION PASS")


def main():
    if len(sys.argv)==2 and sys.argv[1]=='--self-test': numerical_self_test(); return
    if len(sys.argv)!=2: fail("usage: transform_26487_reconstruction_correctness_latency_v2.py <candidate-root> | --self-test")
    root=Path(sys.argv[1]).resolve()
    for rel,want in PRE.items():
        p=root/rel
        if want is None:
            if p.exists(): fail("new-file precondition violated "+rel)
        else:
            if not p.is_file(): fail("missing exact-26486 input "+rel)
            got=sha(p)
            if got!=want: fail(f"exact-26486 prehash mismatch {rel} got={got} want={want}")
    for rel,blob in BLOBS.items():
        p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(gzip.decompress(base64.b64decode(blob)))
    validate_post(root)
    print("26487 V2 transform PASS")

if __name__=='__main__': main()
